  function L(){return window.__widgets&&window.__widgets._lists;}
  function boxMain(id){var b=document.querySelector('[data-wid="'+id+'"]')||null;return b;}
  /* ---- drag to reorder ---- */
  function handles(list,kind){Array.prototype.forEach.call(list.querySelectorAll('.wli[data-id]'),function(li){if(li.querySelector('.lui-h'))return;var h=document.createElement('span');h.className='lui-h';h.textContent='\u22ee\u22ee';h.title='Drag to reorder';li.insertBefore(h,li.firstChild);});}
  function wireDrag(list,kind){if(list.__lui)return;list.__lui=1;
    var mo=new MutationObserver(function(){handles(list,kind);});mo.observe(list,{childList:true});handles(list,kind);
    list.addEventListener('pointerdown',function(e){var h=e.target.closest('.lui-h');if(!h||e.button>0)return;e.preventDefault();e.stopPropagation();
      var li=h.closest('.wli'),id=li.getAttribute('data-id'),tgt=null,after=false;li.classList.add('lui-drag');document.body.classList.add('lui-dragging');
      try{h.setPointerCapture(e.pointerId);}catch(_){}
      function clr(){Array.prototype.forEach.call(list.querySelectorAll('.lui-drop-b,.lui-drop-a'),function(x){x.classList.remove('lui-drop-b','lui-drop-a');});}
      function mv(ev){ev.preventDefault();var r=list.getBoundingClientRect();if(ev.clientY<r.top+12)list.scrollTop-=8;else if(ev.clientY>r.bottom-12)list.scrollTop+=8;
        clr();tgt=null;var rows=list.querySelectorAll('.wli[data-id]');for(var i=0;i<rows.length;i++){var b=rows[i].getBoundingClientRect();if(ev.clientY>=b.top&&ev.clientY<=b.bottom){if(rows[i]!==li){tgt=rows[i];after=ev.clientY>b.top+b.height/2;tgt.classList.add(after?'lui-drop-a':'lui-drop-b');}break;}}}
      function up(){h.removeEventListener('pointermove',mv);h.removeEventListener('pointerup',up);h.removeEventListener('pointercancel',up);clr();li.classList.remove('lui-drag');document.body.classList.remove('lui-dragging');
        if(!tgt)return;var A=L()&&L()[kind];if(!A)return;var arr=A.get(),from=-1,to=-1,tid=tgt.getAttribute('data-id');
        for(var i=0;i<arr.length;i++)if(arr[i].id===id)from=i;if(from<0)return;var it=arr.splice(from,1)[0];
        for(i=0;i<arr.length;i++)if(arr[i].id===tid)to=i;if(to<0){arr.splice(from,0,it);return;}arr.splice(after?to+1:to,0,it);A.save();A.render();}
      h.addEventListener('pointermove',mv);h.addEventListener('pointerup',up);h.addEventListener('pointercancel',up);},true);}
  /* ---- shopping sites ---- */
  function mine(){try{var v=JSON.parse(localStorage.getItem('hinge-w-shoplinks')||'[]');return Array.isArray(v)?v:[];}catch(e){return [];}}
  function sites(main){if(main.querySelector('.lui-sites'))return;var d=document.createElement('details');d.className='lui-sites';d.open=true;
    d.innerHTML='<summary>Shopping sites</summary><div class="lui-sl"></div><div class="lui-add"><input class="lui-n" placeholder="Name" maxlength="40"><input class="lui-u" placeholder="https://\u2026" maxlength="300"><button type="button" class="wbtn lui-ab">Add link</button></div>';
    main.appendChild(d);var sl=d.querySelector('.lui-sl');
    function paint(){var m=mine(),h=m.length?'<div class="lui-g">My links</div>'+m.map(function(x,i){return '<a href="'+esc(x.u)+'" target="_blank" rel="noopener noreferrer">'+esc(x.n)+'</a><span class="lui-x" data-i="'+i+'" title="Remove">\u00d7</span>';}).join(''):'';
      h+=SHOPS.map(function(g){return '<div class="lui-g">'+esc(g[0])+'</div>'+g[1].map(function(x){return '<a href="'+esc(x[1])+'" target="_blank" rel="noopener noreferrer">'+esc(x[0])+'</a>';}).join('');}).join('');sl.innerHTML=h;}
    paint();
    ['pointerdown','mousedown'].forEach(function(t){d.addEventListener(t,function(e){e.stopPropagation();});});
    d.addEventListener('keydown',function(e){e.stopPropagation();if(e.key==='Enter'&&e.target.tagName==='INPUT')add();});
    function add(){var n=d.querySelector('.lui-n').value.trim(),u=d.querySelector('.lui-u').value.trim();if(!/^https?:\/\//i.test(u))u=u?'https://'+u:'';if(!n||!u)return;var m=mine();m.push({n:n,u:u});localStorage.setItem('hinge-w-shoplinks',JSON.stringify(m));d.querySelector('.lui-n').value=d.querySelector('.lui-u').value='';paint();}
    d.addEventListener('click',function(e){if(e.target.closest('.lui-ab')){add();return;}var x=e.target.closest('.lui-x');if(x){var m=mine();m.splice(+x.dataset.i,1);localStorage.setItem('hinge-w-shoplinks',JSON.stringify(m));paint();return;}
      var a=e.target.closest('.lui-sl a');if(a){e.preventDefault();e.stopPropagation();window.open(a.href,'_blank','noopener');}});}
  /* ---- find the Notes / Shopping boxes (by their unique inputs) ---- */
  function scan(){var nt=document.querySelector('textarea.wnt');if(nt){var m=nt.parentNode;m.classList.add('lui-notes');var l=m.querySelector('.wlist');if(l)wireDrag(l,'notes');}
    var si=document.querySelector('input.wsi');if(si){var m2=si.closest('.wrow').parentNode;m2.classList.add('lui-shop');var l2=m2.querySelector('.wlist');if(l2)wireDrag(l2,'shopping');sites(m2);}}
  setInterval(scan,800);scan();
  /* ---- Call box: Esc closes; closing hangs up an active voice call ---- */
  function call(){return document.querySelector('section.call');}
  function hang(){try{var v=window.__voice;if(v&&v.inCall&&v.inCall()&&v.hangUp)v.hangUp();}catch(e){}}
  document.addEventListener('click',function(e){if(e.target.closest&&e.target.closest('section.call .callx'))hang();},true);
  document.addEventListener('keydown',function(e){if(e.key!=='Escape')return;var c=call();if(!c||c.classList.contains('closed')||c.offsetParent===null)return;
    var a=document.activeElement;if(a&&a!==document.body&&!c.contains(a))return;var x=c.querySelector('.callx');if(!x)return;hang();x.dispatchEvent(new MouseEvent('click',{bubbles:true}));});
